import { cookies, headers } from 'next/headers';

export default async function UserPreferences() {
  const cookieStore = await cookies();
  const theme = cookieStore.get('theme')?.value ?? 'light';

  const headersList = await headers();
  const acceptLanguage = headersList.get('accept-language');

  return (
    <div className="p-4 border rounded shadow-sm my-4">
      <h2 className="text-xl font-bold mb-2">User Preferences</h2>
      <p>
        <strong>Theme:</strong> {theme}
      </p>
      <p>
        <strong>Preferred Language:</strong> {acceptLanguage || 'Not specified'}
      </p>
    </div>
  );
}

import UserPreferences from './components/UserPreferences';

export default function Home() {
  return (
    <main>
      <h1>User Preferences</h1>
      <UserPreferences />
    </main>
  );
}

